// Worker entry: the OpenNext app plus what Next.js cannot do itself here — chat WebSockets
// through one Inbox Durable Object per user, and the daily watchdog run (cron).
import { DurableObject } from "cloudflare:workers";
// @ts-expect-error generated by `opennextjs-cloudflare build`
import openNext from "../.open-next/worker.js";
import { verifyWsToken } from "../src/lib/ws-token";

/**
 * One per user: holds the WebSockets of the user's open tabs and forwards every event the app
 * pushes (new message, unread count) to all of them. Hibernation keeps idle sockets free.
 */
export class Inbox extends DurableObject<CloudflareEnv> {
  async fetch(request: Request): Promise<Response> {
    if (request.headers.get("upgrade") === "websocket") {
      const pair = new WebSocketPair();
      this.ctx.acceptWebSocket(pair[1]);
      return new Response(null, { status: 101, webSocket: pair[0] });
    }
    const event = await request.text();
    for (const socket of this.ctx.getWebSockets()) {
      try {
        socket.send(event);
      } catch {
        // A socket that is closing; the browser reconnects on its own.
      }
    }
    return new Response("ok");
  }

  async webSocketMessage(socket: WebSocket, data: string | ArrayBuffer) {
    if (data === "ping") socket.send("pong");
  }

  async webSocketClose(socket: WebSocket, code: number) {
    socket.close(code === 1005 ? 1000 : code, "closed");
  }
}

export default {
  async fetch(request: Request, env: CloudflareEnv, ctx: ExecutionContext): Promise<Response> {
    const url = new URL(request.url);
    if (url.pathname === "/ws/zpravy") {
      if (request.headers.get("upgrade") !== "websocket") return new Response("Expected WebSocket", { status: 426 });
      const userId = await verifyWsToken(url.searchParams.get("token") ?? "", env.BETTER_AUTH_SECRET);
      if (!userId) return new Response("Unauthorized", { status: 401 });
      return env.INBOX.get(env.INBOX.idFromName(userId)).fetch(request);
    }
    return openNext.fetch(request, env, ctx);
  },

  async scheduled(_: ScheduledController, env: CloudflareEnv, ctx: ExecutionContext) {
    // Runs the watchdog inside the app; the secret header keeps the route closed to everyone else.
    const request = new Request(`${env.BETTER_AUTH_URL}/api/cron/hlidaci-pes/`, {
      method: "POST",
      headers: { "x-cron-secret": env.BETTER_AUTH_SECRET },
    });
    ctx.waitUntil(openNext.fetch(request, env, ctx));
  },
};
